"""Read-only summary of mailbox letters."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re


RESOLVING = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}
NAME_PREFIX = re.compile(r"[0-9]{8}T[0-9]{4}[-_]")


def parse_letter(path, now):
    lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    if not lines or lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    if any(not fields.get(key) for key in ("id", "from", "to", "status", "at")):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields["at"])
    except ValueError:
        return None, "no_field"
    if at.tzinfo is None:
        at = at.replace(tzinfo=now.tzinfo)
    if not NAME_PREFIX.match(path.name):
        return None, "bad_name"
    try:
        datetime.strptime(path.name[:13], "%Y%m%dT%H%M")
    except ValueError:
        return None, "bad_name"
    return {"id": fields["id"], "from": fields["from"],
            "to": fields["to"], "status": fields["status"],
            "at": at, "re": fields.get("re", "")}, None


def mailbox_files(inbox):
    for directory, where in ((inbox, "inbox"), (inbox / "done", "done")):
        if not directory.is_dir() or directory.is_symlink():
            continue
        for path in directory.iterdir():
            if (not path.name.startswith(".") and path.suffix == ".md"
                    and not path.is_symlink() and path.is_file()):
                yield path, where


def summarize(root, now):
    boxes = {}
    entries = []
    for mailbox in sorted(root.iterdir(), key=lambda path: path.name):
        if mailbox.name.startswith(".") or mailbox.is_symlink() or not mailbox.is_dir():
            continue
        inbox = mailbox / "inbox"
        if inbox.is_symlink() or not inbox.is_dir():
            continue
        boxes[mailbox.name] = {"inbox": {}, "done": 0}
        for path, where in mailbox_files(inbox):
            entries.append((path.relative_to(root).as_posix(), path, where, mailbox.name))

    seen = set()
    letters = []
    bad = []
    for relative, path, where, box in sorted(entries):
        letter, why = parse_letter(path, now)
        if why is None and letter["id"] in seen:
            why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        seen.add(letter["id"])
        letter["where"] = where
        letters.append(letter)
        if where == "inbox":
            counts = boxes[box]["inbox"]
            counts[letter["status"]] = counts.get(letter["status"], 0) + 1
        else:
            boxes[box]["done"] += 1

    resolved = {letter["re"] for letter in letters
                if letter["status"] in RESOLVING and letter["re"]}
    opened = [{"id": letter["id"], "from": letter["from"],
               "to": letter["to"], "where": letter["where"],
               "age_min": (now - letter["at"]) // timedelta(minutes=1)}
              for letter in letters
              if letter["status"] == "REQUEST" and letter["id"] not in resolved]
    opened.sort(key=lambda letter: (letter["to"], letter["id"]))
    bad.sort(key=lambda item: (item["file"], item["why"]))
    return {"v": 1, "open": opened, "boxes": boxes, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Summarize mailbox letters without changing them")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO timestamp with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False,
                     allow_nan=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
